import{_ as p,a0 as o,w as d,s as h,I as a,x as e,a1 as t,A as l,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"基于 Tmux 的多会话终端管理示例 | LCTT x X-CMD","titleTemplate":false,"description":"基于 Tmux 的多会话终端管理示例 | LCTT (202102) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"基于 Tmux 的多会话终端管理示例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"基于 Tmux 的多会话终端管理示例 | LCTT (202102) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202102/20190610 Tmux Command Examples To Manage Multiple Terminal Sessions","title":"基于 Tmux 的多会话终端管理示例","tag":"202102","desc":""},"relativePath":"202102/20190610 Tmux Command Examples To Manage Multiple Terminal Sessions.md","filePath":"[post].md"}'),r={name:"202102/20190610 Tmux Command Examples To Manage Multiple Terminal Sessions.md"};function u(m,s,c,g,x,b){const i=o("Link");return d(),h("div",null,[s[22]||(s[22]=a("h1",{id:"基于-tmux-的多会话终端管理示例",tabindex:"-1"},[e("基于 Tmux 的多会话终端管理示例 "),a("a",{class:"header-anchor",href:"#基于-tmux-的多会话终端管理示例","aria-label":"Permalink to “基于 Tmux 的多会话终端管理示例”"},"​")],-1)),s[23]||(s[23]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202102/11/101058ffso6wzzw94wm2ng.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=e("我们已经了解到如何通过 ",-1)),t(i,{href:"https://www.ostechnix.com/screen-command-examples-to-manage-multiple-terminal-sessions/"},{default:l(()=>[...s[0]||(s[0]=[e("GNU Screen",-1)])]),_:1}),s[2]||(s[2]=e(" 进行多会话管理。今天，我们将要领略另一个著名的管理会话的命令行实用工具 ",-1)),s[3]||(s[3]=a("strong",null,"Tmux",-1)),s[4]||(s[4]=e("。类似 GNU Screen，Tmux 是一个帮助我们在单一终端窗口中创建多个会话，同一时间内同时运行多个应用程序或进程的终端复用工具。Tmux 自由、开源并且跨平台，支持 Linux、OpenBSD、FreeBSD、NetBSD 以及 Mac OS X。本文将讨论 Tmux 在 Linux 系统下的高频用法。",-1))]),s[24]||(s[24]=n(`<h3 id="linux-下安装-tmux" tabindex="-1">Linux 下安装 Tmux <a class="header-anchor" href="#linux-下安装-tmux" aria-label="Permalink to “Linux 下安装 Tmux”">​</a></h3><p>Tmux 可以在绝大多数的 Linux 官方仓库下获取。</p><p>在 Arch Linux 或它的变种系统下，执行下列命令来安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S tmux</span></span></code></pre></div><p>Debian、Ubuntu 或 Linux Mint：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install tmux</span></span></code></pre></div><p>Fedora：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install tmux</span></span></code></pre></div><p>RHEL 和 CentOS：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install tmux</span></span></code></pre></div><p>SUSE/openSUSE：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo zypper install tmux</span></span></code></pre></div><p>以上，我们已经完成 Tmux 的安装。之后我们继续看看一些 Tmux 示例。</p><h3 id="tmux-命令示例-多会话管理" tabindex="-1">Tmux 命令示例: 多会话管理 <a class="header-anchor" href="#tmux-命令示例-多会话管理" aria-label="Permalink to “Tmux 命令示例: 多会话管理”">​</a></h3><p>Tmux 默认所有命令的前置命令都是 <code>Ctrl+b</code>，使用前牢记这个快捷键即可。</p><blockquote><p><strong>注意</strong>：<strong>Screen</strong> 的前置命令都是 <code>Ctrl+a</code>.</p></blockquote><h4 id="创建-tmux-会话" tabindex="-1">创建 Tmux 会话 <a class="header-anchor" href="#创建-tmux-会话" aria-label="Permalink to “创建 Tmux 会话”">​</a></h4><p>在终端中运行如下命令创建 Tmux 会话并附着进入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux</span></span></code></pre></div><p>抑或，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux new</span></span></code></pre></div><p>一旦进入 Tmux 会话，你将看到一个 <strong>沉在底部的绿色的边栏</strong>，如下图所示。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Tmux-session.png" alt=""></p><p><em>创建 Tmux 会话</em></p><p>这个绿色的边栏能很容易提示你当前是否身处 Tmux 会话当中。</p><h4 id="退出-tmux-会话" tabindex="-1">退出 Tmux 会话 <a class="header-anchor" href="#退出-tmux-会话" aria-label="Permalink to “退出 Tmux 会话”">​</a></h4><p>退出当前 Tmux 会话仅需要使用 <code>Ctrl+b</code> 和 <code>d</code>。无需同时触发这两个快捷键，依次按下 <code>Ctrl+b</code> 和 <code>d</code> 即可。</p><p>退出当前会话后，你将能看到如下输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[detached (from session 0)]</span></span></code></pre></div><h4 id="创建有名会话" tabindex="-1">创建有名会话 <a class="header-anchor" href="#创建有名会话" aria-label="Permalink to “创建有名会话”">​</a></h4><p>如果使用多个会话，你很可能会混淆运行在多个会话中的应用程序。这种情况下，我们需要会话并赋予名称。譬如需要 web 相关服务的会话，就创建一个名称为 “webserver”（或任意一个其他名称） 的 Tmux 会话。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux new -s webserver</span></span></code></pre></div><p>这里是新的 Tmux 有名会话：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Named-Tmux-session.png" alt=""></p><p><em>拥有自定义名称的 Tmux 会话</em></p><p>如你所见上述截图，这个 Tmux 会话的名称已经被标注为 “webserver”。如此，你可以在多个会话中，轻易的区分应用程序的所在。</p><p>退出会话，轻按 <code>Ctrl+b</code> 和 <code>d</code>。</p><h4 id="查看-tmux-会话清单" tabindex="-1">查看 Tmux 会话清单 <a class="header-anchor" href="#查看-tmux-会话清单" aria-label="Permalink to “查看 Tmux 会话清单”">​</a></h4><p>查看 Tmux 会话清单，执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux ls</span></span></code></pre></div><p>示例输出：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/List-Tmux-sessions.png" alt=""></p><p><em>列出 Tmux 会话</em></p><p>如你所见，我们开启了两个 Tmux 会话。</p><h4 id="创建非附着会话" tabindex="-1">创建非附着会话 <a class="header-anchor" href="#创建非附着会话" aria-label="Permalink to “创建非附着会话”">​</a></h4><p>有时候，你可能想要简单创建会话，但是并不想自动切入该会话。</p><p>创建一个非附着会话，并赋予名称 “ostechnix”，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux new -s ostechnix -d</span></span></code></pre></div><p>上述命令将会创建一个名为 “ostechnix” 的会话，但是并不会附着进入。</p><p>你可以通过使用 <code>tmux ls</code> 命令验证：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Create-detached-sessions.png" alt=""></p><p><em>创建非附着会话</em></p><h4 id="附着进入-tmux-会话" tabindex="-1">附着进入 Tmux 会话 <a class="header-anchor" href="#附着进入-tmux-会话" aria-label="Permalink to “附着进入 Tmux 会话”">​</a></h4><p>通过如下命令，你可以附着进入最后一个被创建的会话：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux attach</span></span></code></pre></div><p>抑或，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux a</span></span></code></pre></div><p>如果你想附着进入任意一个指定的有名会话，譬如 “ostechnix”，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux attach -t ostechnix</span></span></code></pre></div><p>或者，简写为：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux a -t ostechnix</span></span></code></pre></div><h4 id="关闭-tmux-会话" tabindex="-1">关闭 Tmux 会话 <a class="header-anchor" href="#关闭-tmux-会话" aria-label="Permalink to “关闭 Tmux 会话”">​</a></h4><p>当你完成或者不再需要 Tmux 会话，你可以通过如下命令关闭：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux kill-session -t ostechnix</span></span></code></pre></div><p>当身处该会话时，使用 <code>Ctrl+b</code> 以及 <code>x</code>。点击 <code>y</code> 来关闭会话。</p><p>可以通过 <code>tmux ls</code> 命令验证。</p><p>关闭所有 Tmux 服务下的所有会话，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tmux kill-server</span></span></code></pre></div><p>谨慎！这将终止所有 Tmux 会话，并不会产生任何警告，即便会话存在运行中的任务。</p><p>如果不存在活跃的 Tmux 会话，将看到如下输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tmux ls</span></span>
<span class="line"><span>no server running on /tmp/tmux-1000/default</span></span></code></pre></div><h4 id="切割-tmux-窗口" tabindex="-1">切割 Tmux 窗口 <a class="header-anchor" href="#切割-tmux-窗口" aria-label="Permalink to “切割 Tmux 窗口”">​</a></h4><p>切割窗口成多个小窗口，在 Tmux 中，这个叫做 “Tmux 窗格”。每个窗格中可以同时运行不同的程序，并同时与所有的窗格进行交互。每个窗格可以在不影响其他窗格的前提下可以调整大小、移动位置和控制关闭。我们可以以水平、垂直或者二者混合的方式切割屏幕。</p><h5 id="水平切割窗格" tabindex="-1">水平切割窗格 <a class="header-anchor" href="#水平切割窗格" aria-label="Permalink to “水平切割窗格”">​</a></h5><p>欲水平切割窗格，使用 <code>Ctrl+b</code> 和 <code>&quot;</code>（半个双引号）。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Horizontal-split.png" alt=""></p><p><em>水平切割 Tmux 窗格</em></p><p>可以使用组合键进一步切割面板。</p><h5 id="垂直切割窗格" tabindex="-1">垂直切割窗格 <a class="header-anchor" href="#垂直切割窗格" aria-label="Permalink to “垂直切割窗格”">​</a></h5><p>垂直切割面板，使用 <code>Ctrl+b</code> 和 <code>%</code>。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Vertical-split.png" alt=""></p><p><em>垂直切割 Tmux 窗格</em></p><h5 id="水平、垂直混合切割窗格" tabindex="-1">水平、垂直混合切割窗格 <a class="header-anchor" href="#水平、垂直混合切割窗格" aria-label="Permalink to “水平、垂直混合切割窗格”">​</a></h5><p>我们也可以同时采用水平和垂直的方案切割窗格。看看如下截图：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Split-Panes.png" alt=""></p><p><em>切割 Tmux 窗格</em></p><p>首先，我通过 <code>Ctrl+b</code> <code>&quot;</code> 水平切割，之后通过 <code>Ctrl+b</code> <code>%</code> 垂直切割下方的窗格。</p><p>如你所见，每个窗格下我运行了不同的程序。</p><h5 id="切换窗格" tabindex="-1">切换窗格 <a class="header-anchor" href="#切换窗格" aria-label="Permalink to “切换窗格”">​</a></h5><p>通过 <code>Ctrl+b</code> 和方向键（上下左右）切换窗格。</p><h5 id="发送命令给所有窗格" tabindex="-1">发送命令给所有窗格 <a class="header-anchor" href="#发送命令给所有窗格" aria-label="Permalink to “发送命令给所有窗格”">​</a></h5><p>之前的案例中，我们在每个窗格中运行了三个不同命令。其实，也可以发送相同的命令给所有窗格。</p><p>为此，使用 <code>Ctrl+b</code> 然后键入如下命令，之后按下回车：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:setw synchronize-panes</span></span></code></pre></div><p>现在在任意窗格中键入任何命令。你将看到相同命令影响了所有窗格。</p><h5 id="交换窗格" tabindex="-1">交换窗格 <a class="header-anchor" href="#交换窗格" aria-label="Permalink to “交换窗格”">​</a></h5><p>使用 <code>Ctrl+b</code> 和 <code>o</code> 交换窗格。</p><h5 id="展示窗格号" tabindex="-1">展示窗格号 <a class="header-anchor" href="#展示窗格号" aria-label="Permalink to “展示窗格号”">​</a></h5><p>使用 <code>Ctrl+b</code> 和 <code>q</code> 展示窗格号。</p><h5 id="终止窗格" tabindex="-1">终止窗格 <a class="header-anchor" href="#终止窗格" aria-label="Permalink to “终止窗格”">​</a></h5><p>要关闭窗格，直接键入 <code>exit</code> 并且按下回车键。或者，按下 <code>Ctrl+b</code> 和 <code>x</code>。你会看到确认信息。按下 <code>y</code> 关闭窗格。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/06/Kill-panes.png" alt=""></p><p><em>关闭窗格</em></p><h5 id="放大和缩小-tmux-窗格" tabindex="-1">放大和缩小 Tmux 窗格 <a class="header-anchor" href="#放大和缩小-tmux-窗格" aria-label="Permalink to “放大和缩小 Tmux 窗格”">​</a></h5><p>我们可以将 Tmux 窗格放大到当前终端窗口的全尺寸，以获得更好的文本可视性，并查看更多的内容。当你需要更多的空间或专注于某个特定的任务时，这很有用。在完成该任务后，你可以将 Tmux 窗格缩小（取消放大）到其正常位置。更多详情请看以下链接。</p>`,105)),a("ul",null,[a("li",null,[t(i,{href:"https://ostechnix.com/how-to-zoom-tmux-panes-for-better-text-visibility/"},{default:l(()=>[...s[5]||(s[5]=[e("如何缩放 Tmux 窗格以提高文本可见度？",-1)])]),_:1})])]),s[25]||(s[25]=a("h4",{id:"自动启动-tmux-会话",tabindex:"-1"},[e("自动启动 Tmux 会话 "),a("a",{class:"header-anchor",href:"#自动启动-tmux-会话","aria-label":"Permalink to “自动启动 Tmux 会话”"},"​")],-1)),s[26]||(s[26]=a("p",null,"当通过 SSH 与远程系统工作时，在 Tmux 会话中运行一个长期运行的进程总是一个好的做法。因为，它可以防止你在网络连接突然中断时失去对运行进程的控制。避免这个问题的一个方法是自动启动 Tmux 会话。更多详情，请参考以下链接。",-1)),a("ul",null,[a("li",null,[t(i,{href:"https://ostechnix.com/autostart-tmux-session-on-remote-system-when-logging-in-via-ssh/"},{default:l(()=>[...s[6]||(s[6]=[e("通过 SSH 登录远程系统时自动启动 Tmux 会话",-1)])]),_:1})])]),s[27]||(s[27]=n('<h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>这个阶段下，你已经获得了基本的 Tmux 技能来进行多会话管理，更多细节，参阅 man 页面。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man tmux</span></span></code></pre></div><p>GNU Screen 和 Tmux 工具都能透过 SSH 很好的管理远程服务器。学习 Screen 和 Tmux 命令，像个行家一样，彻底通过这些工具管理远程服务器。</p><hr>',5)),a("p",null,[s[8]||(s[8]=e("via: ",-1)),t(i,{href:"https://www.ostechnix.com/tmux-command-examples-to-manage-multiple-terminal-sessions/"},{default:l(()=>[...s[7]||(s[7]=[e("https://www.ostechnix.com/tmux-command-examples-to-manage-multiple-terminal-sessions/",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=e("作者：",-1)),t(i,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...s[9]||(s[9]=[e("sk",-1)])]),_:1}),s[14]||(s[14]=e(" 选题：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[10]||(s[10]=[e("lujun9972",-1)])]),_:1}),s[15]||(s[15]=e(" 译者：",-1)),t(i,{href:"https://github.com/chensanle"},{default:l(()=>[...s[11]||(s[11]=[e("chensanle",-1)])]),_:1}),s[16]||(s[16]=e(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:l(()=>[...s[12]||(s[12]=[e("wxy",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=e("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[17]||(s[17]=[e("LCTT",-1)])]),_:1}),s[20]||(s[20]=e(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:l(()=>[...s[18]||(s[18]=[e("Linux中国",-1)])]),_:1}),s[21]||(s[21]=e(" 荣誉推出",-1))])])}const C=p(r,[["render",u]]);export{T as __pageData,C as default};
